const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cell=(id,label,address,value,extra={})=>({id,label,address,value,...extra});
const frame=(title,line,why,cells,links=[],changed=[],watch=[],prediction=null)=>({title,line,why,cells,links,changed,watch,prediction});
function pointerChange(a='a',b='b',p='p',av=10,bv=20,newValue=9,reverse=false){
 const cells=(x,y,target=null)=>[cell('a',a,'0x2000',String(x)),cell('b',b,'0x2040',String(y)),cell('p',p,'0x2100',target==='a'?'0x2000':target==='b'?'0x2040':'尚未声明',{hidden:target===null,pointer:true})];
 const code=[`int ${a} = ${av};`,`int ${b} = ${bv};`,`int *${p} = &${a};`,...(reverse?[`*${p} = ${newValue};`,`${p} = &${b};`]:[`${p} = &${b};`,`*${p} = ${newValue};`])];
 const init=[frame('先有两个整数',-1,`${a} 和 ${b} 是两个独立对象。下面从创建指针开始，一次执行一行。`,cells(av,bv)),frame('把地址存入指针',2,`${p} 中存的是 ${a} 的地址 0x2000，不是整数 ${av}。绿色箭头表示可以沿这个地址找到 ${a}。`,cells(av,bv,'a'),[['p','a']],['p'],[[p,'0x2000'],[`*${p}`,String(av)]])];
 const frames=reverse?[...init,
 frame('沿地址写入目标',3,`左边是 *${p}：沿箭头把 ${a} 的内容改为 ${newValue}。${p} 保存的地址仍是 0x2000。`,cells(newValue,bv,'a'),[['p','a']],['a'],[[a,String(newValue)],[p,'0x2000']]),
 frame('只改变指针指向',4,`左边是 ${p}：把它保存的地址改为 ${b} 的地址。${a} 已经写入的 ${newValue} 保留，${b} 的内容没有改变。`,cells(newValue,bv,'b'),[['p','b']],['p'],[[a,String(newValue)],[b,String(bv)],[`*${p}`,String(bv)]])]:[...init,
 frame('只改变指针指向',3,`左边是 ${p}，所以只改它保存的地址。箭头换到 ${b}，两个整数的内容都没有变。`,cells(av,bv,'b'),[['p','b']],['p'],[[a,String(av)],[b,String(bv)],[p,'0x2040']],{prompt:`执行 ${p} = &${b}; 后，${a}、${b} 的整数内容会怎样？`,options:[`仍为 ${av}、${bv}`,`都变为 ${bv}`,`${a} 变为 ${bv}，${b} 不变`],answer:0,why:'赋值左边是指针本身，两个整数格子都没有被写入。'}),
 frame('沿新地址写入目标',4,`现在箭头指向 ${b}。*${p} = ${newValue} 改的是 ${b}，${a} 保持 ${av}，${p} 中的地址也没有变。`,cells(av,newValue,'b'),[['p','b']],['b'],[[a,String(av)],[b,String(newValue)],[p,'0x2040']],{prompt:`下一行 *${p} = ${newValue}; 会修改哪个对象？`,options:[a,b,p],answer:1,why:'*p 访问当前目标；先看箭头，再判断要写哪个格子。'})];
 return {title:'p = 与 *p =：地址和内容分开看',code,frames,note:'本图地址是教学示意，不代表实际布局；指针格子的地址与它保存的地址是两回事。',experiment:true};
}
function declaration(x='x',p='p',value=10){const c=(has=false)=>[cell('x',x,'0x2000',String(value)),cell('p',p,'0x2100',has?'0x2000':'尚未声明',{hidden:!has,pointer:true})];return {title:'一个指针，两个地址',code:[`int ${x} = ${value};`,`int *${p} = &${x};`,`// ${p}、&${p}、*${p} 分别是什么？`],note:'地址是示意。对象指针自身的字节数由平台决定，本图不按格子宽度表示大小。',frames:[frame('先看目标变量',-1,`${x} 的内容是 ${value}，位置用 0x2000 表示。指针还没建立。`,c()),frame('保存目标地址',1,`${p} 被创建在另一个位置 0x2100；里面保存的是 ${x} 的位置 0x2000。`,c(true),[['p','x']],['p']),frame('分开读三种表达式',2,`${p} 读取地址值；&${p} 取得指针自己的位置；*${p} 沿地址访问 ${x} 的内容。`,c(true),[['p','x']],[],[[p,'0x2000'],[`&${p}`,'0x2100'],[`*${p}`,String(value)]])]};}
function dereference(x='x',y='y',p='p',v=10,newValue=7){const c=(target=v,copy=null)=>[cell('x',x,'0x2000',String(target)),cell('y',y,'0x2040',copy===null?'尚未声明':String(copy),{hidden:copy===null}),cell('p',p,'0x2100','0x2000',{pointer:true})];return {title:'读取是复制，写入是修改目标',code:[`int ${x} = ${v};`,`int *${p} = &${x};`,`int ${y} = *${p};`,`*${p} = ${newValue};`,`// 再观察 ${x}、${y}、${p}`],note:'第 0 步已建立有效指针；地址是示意，所有对象在这段演示中仍存活。',frames:[frame('已有一个有效指针',-1,`${p} 指向 ${x}。先沿箭头找到目标，再决定读取还是写入。`,c(),[['p','x']]),frame('读取并复制',2,`*${p} 读取 ${x} 当前的 ${v}，复制给新变量 ${y}。${y} 有自己的格子，并没有成为 ${x} 的别名。`,c(v,v),[['p','x']],['y']),frame('通过指针写入',3,`*${p} 位于赋值左边，把 ${newValue} 写到 ${x}。地址没变，之前复制给 ${y} 的数值也不会自动变化。`,c(newValue,v),[['p','x']],['x'],[],{prompt:`写入后，之前复制出来的 ${y} 会怎样？`,options:[`保持 ${v}`,`跟着变成 ${newValue}`,'变成地址'],answer:0,why:'普通整数赋值只在当时复制一次，不建立持续联动。'}),frame('分别读取当前内容',4,`${x} 是修改后的目标；${y} 是先前的副本。*${p} 读取的是目标现在的内容。`,c(newValue,v),[['p','x']],[],[[x,String(newValue)],[y,String(v)],[`*${p}`,String(newValue)]])]};}
function arrayModel(values=[10,20,30],write=7){const c=(arr=values,target=null)=>[...arr.map((v,i)=>cell('a'+i,`a[${i}]`,'0x'+(0x2000+i*4).toString(16),String(v))),cell('p','p','0x2100',target===null?'尚未声明':'0x'+(0x2000+target*4).toString(16),{hidden:target===null,pointer:true})];return {title:'数组下标与指针移动',code:[`int a[3] = {${values.join(', ')}};`,`int *p = &a[0];`,`p = p + 1;`,`*p = ${write};`,`// a[3] 不存在，不可读写`],note:'本例假设 int 为 4 字节，数组元素连续；指针变量本身的地址单独示意。',frames:[frame('三个元素，下标从零开始',-1,'每一格是一个独立 int 元素。3 是数量；有效下标为 0、1、2。',c()),frame('指向首元素',1,'&a[0] 取得第一项地址，p 保存这个地址。数组中的整数没有被复制进 p。',c(values,0),[['p','a0']],['p']),frame('前进一个 int',2,'p + 1 按所指类型移动。这里跨过 4 字节，到 a[1]，不是把整数加一。',c(values,1),[['p','a1']],['p']),frame('写入当前元素',3,`现在 p 指向 a[1]，所以只把第二项写成 ${write}。其他元素保持原值。`,c([values[0],write,values[2]],1),[['p','a1']],['a1'],[],{prompt:'执行 *p = 新值，会修改哪一项？',options:['a[0]','a[1]','全部元素'],answer:1,why:'先追踪指针移动后的地址，才知道解引用访问哪一项。'}),frame('检查范围',4,'a[3] 已经在三个元素之后。允许形成尾后指针作比较，不允许在那里读取或写入元素。',c([values[0],write,values[2]],1),[['p','a1']],[],[['最后有效下标','2'],['元素数量','3']])]};}
function sizeofModel(v=50){const cells=[cell('x','x','示意位置',String(v),{detail:'int 对象：4 字节'}),cell('a','a[3]','连续三个元素','10 / 20 / 30',{detail:'完整数组：12 字节'}),cell('p','p','独立位置','a 的首元素地址',{detail:'指针对象：4 字节',pointer:true})];return {title:'sizeof：问空间，不问内容',code:[`int x = ${v};`,`int a[3] = {10, 20, 30};`,`int *p = a;`,`sizeof(x);`,`sizeof(a);`,`sizeof(p);`,`sizeof(a) / sizeof(a[0]);`],note:'本例明确采用 int 为 4 字节、对象指针为 4 字节的环境；换平台时应重新核对。',frames:[frame('先分清三种对象',-1,`x 里面的 ${v} 是数值；a 是完整数组；p 是另外一个保存地址的对象。`,cells),frame('询问整数对象的大小',3,'sizeof(x) 根据普通 int 类型得到 4 字节，x 的数值不参与这个结果。',cells,[],['x'],[['sizeof(x)','4 字节'],['x 的内容',String(v)]]),frame('询问完整数组的大小',4,'a 有三个 int，每个 4 字节，整个数组为 12 字节。这里没有先把 a 转成指针。',cells,[],['a'],[['sizeof(a)','3 × 4 = 12 字节']]),frame('询问指针自身的大小',5,'p 保存数组首元素地址，但 sizeof(p) 只问指针对象本身占多少空间，不沿地址去数数组元素。',cells,[],['p'],[['sizeof(p)','本例为 4 字节']],{prompt:'p 指向三个元素后，sizeof(p) 会变成数组总大小吗？',options:['不会，求的是指针自身','会，指向多少就占多少','取决于数组内容'],answer:0,why:'指针保存地址，不把目标对象装进自己的存储空间。'}),frame('从字节数求元素数',6,'总字节数除以一个元素的字节数，单位相消，得到元素数量。只适用于这里的完整数组。',cells,[],[],[['计算','12 / 4'],['元素数','3']])]};}
function functionModel(v=10,newValue=7){const c=(x=v,n=null,p=false)=>[cell('x','调用者 x','0x2000',String(x)),cell('n','形参 n','0x3000',n===null?'本次调用未创建':String(n),{hidden:n===null}),cell('p','形参 p','0x3100',p?'0x2000':'本次调用未创建',{hidden:!p,pointer:true})];return {title:'传值和传地址：副本里装的是什么',code:[`int x = ${v};`,`void set_value(int n) {`,`    n = ${newValue};`,`}`,`void set_target(int *p) {`,`    *p = ${newValue};`,`}`,`set_value(x);`,`set_target(&x);`],note:'这是用于说明调用顺序的代码片段。图中形参地址只是示意，不承诺真实栈布局。',frames:[frame('调用之前',-1,'先有调用者的 x。函数形参只在相应函数调用时存活。',c()),frame('复制整数给形参',7,'调用 set_value(x)，形参 n 得到 x 当前整数值的副本。两者是不同对象。',c(v,v),[],['n']),frame('只修改形参副本',2,`n = ${newValue} 写入函数内的 n；外面的 x 没有被这句访问。`,c(v,newValue),[],['n']),frame('返回，形参不再存活',3,'本次调用结束，n 的生命周期结束。x 仍存活，保留原来的内容。',c(),[],[],[['调用者 x',String(v)]]),frame('复制地址给指针形参',8,'调用 set_target(&x)，形参 p 得到地址副本，但这个地址仍能找到调用者的 x。',c(v,null,true),[['p','x']],['p']),frame('沿地址修改原对象',5,`*p = ${newValue} 先沿地址找到 x，再把新值写到 x。C 的参数仍是按值传递，区别是这次复制的值是地址。`,c(newValue,null,true),[['p','x']],['x'],[],{prompt:'传 &x 后，形参 p 里保存的是什么？',options:['x 的整数副本','x 的地址副本','整个调用者函数'],answer:1,why:'指针形参也是副本，但保存的地址指向同一个原对象。'}),frame('返回后保留修改结果',6,'指针形参结束生命周期，不会撤销已经对 x 做过的写入。',c(newValue),[],[],[['调用者 x',String(newValue)],['形参 p','不再存活']])]};}
